# Builds ../theme-currency-lists.research.json from the files in raw/. Every number in the text is read from those files.
import json, gzip, os, collections
from lib import NETS
R = 'raw/'
ALL = [n['chainId'] for n in NETS]
NAME = {n['chainId']: n['name'] for n in NETS}
def jz(fn): return json.load(gzip.open(R + fn))
def n(x): return format(int(x), ',')
def amt(x, dec=18, p=2): return format(int(x) / 10 ** dec, ',.%df' % p)

# ---------- part one: lists
base = json.load(open(R + 'base_summary.json'))
cur = {c: jz('currencies_%d.json.gz' % c) for c in (56, 480, 196)}
bal = {c: jz('bal_%d.json.gz' % c) for c in (56, 480, 196, 8453)}
uni = {c: jz('universe_%d.json.gz' % c) for c in (56, 480, 196, 8453)}
nz = {c: sum(1 for v in bal[c].values() if v != 'fail' and int(v) > 0) for c in bal}
testset = jz('base_testset.json.gz')
# ---------- part two
xf = {c: jz('xfer_%d.json.gz' % c) for c in (56, 480, 196, 8453)}
th = {c: jz('third_%d.json.gz' % c) for c in (56, 480, 196, 8453)}
asg = {c: jz('assign_%d.json.gz' % c) for c in (56, 480, 196, 8453)}
why = {c: jz('why_%d.json.gz' % c) for c in (56, 196, 8453)}
whyc = {c: collections.Counter(o['cls'] for o in why[c].values()) for c in why}
mir = {c: json.load(open(R + 'mirror_%d.json' % c)) for c in (56, 480, 196, 8453)}
pr = {c: jz('prices_%d.json.gz' % c) for c in (56, 480, 196, 8453)}
def rejected(c): return sum(1 for t, w in xf[c]['odd'].items() if w[0] != 'callfail' and w[0] > 0 and (w[1] & 1) and not (w[1] & 2))
def thirds(c):
    up = sum(1 for v in th[c]['odd'].values() if int(v[2]) > 0); return up, len(th[c]['odd']) - up
def cats(c): return collections.Counter(h['cat'] for h in asg[c]['hits'])
# ---------- part three
S = json.load(open(R + 'census_summary.json')); S = {int(k): v for k, v in S.items()}
tot_tx = sum(e['txs'] for e in S.values()); tot_rows = sum(e['rows'] for e in S.values()); tot_fl = sum(e['flagged'] for e in S.values())
def cls(c, k): return (S[c].get('classes') or {}).get(k, 0)
def window(c):
    e = S[c]
    return '%s: blocks %s to %s (%s), %s transactions, %s rows, %s flagged' % (e['name'], n(e['B1']), n(e['B2']), 'from the deployment block' if e['full'] else '%s days' % e['days'], n(e['txs']), n(e['rows']), n(e['flagged']))
def classes_text(c):
    e = S[c]; cl = e.get('classes') or {}
    if not e['flagged']: return ''
    order = ['fees', 'spoof', 'surplus', 'accrual', 'sender-charge', 'token-moved', 'token-moved?', 'dust', 'open', 'unread']
    lab = {'fees': 'fee collection', 'spoof': 'spoof log', 'surplus': 'surplus credit', 'accrual': 'credit above the logged transfer by rounding or reflection', 'sender-charge': 'sender charge',
           'token-moved': 'balance moved by the token itself', 'token-moved?': 'balance fell with no pool event and no trace', 'dust': 'difference of at most 10 base units', 'open': 'open', 'unread': 'old state not served'}
    return ' (' + ', '.join('%s %s' % (n(cl[k]), lab[k]) for k in order if cl.get(k)) + ')'
c5 = {c: jz('reread_%d_c5.json.gz' % c)['rows'] for c in (1, 10, 137, 5042, 42161)}
def c5c(c): return dict(collections.Counter(r['cls'] for r in c5[c]))
# BNB rows of cycle 5 inside the new window
bnb = jz('reread_56_w.json.gz')['rows']; bnbk = {(r['tx'], r['token']): r for r in bnb}
old56 = {(u['tx'], u['token']) for u in jz('../../../005/theme-unbacked-claims.work/raw/census_56.json.gz')['unexplained']}
import summary2
old56c = collections.Counter(summary2.refine(bnbk[k], 56) for k in old56 if k in bnbk)
old56tok = collections.defaultdict(set)
for k in old56:
    if k in bnbk: old56tok[summary2.refine(bnbk[k], 56)].add(k[1])
SSAC = '0x0ae7cd10f94fd16a6f9a29a372708718144c46f8'
ss = jz('ssac_payouts.json.gz'); pay = [r for r in ss['rows'] if r['cls'].startswith('surplus')]
pay_amt = [sum(r['trace']['paid']) - int(r['in']) for r in pay]
pay_take = [r for r in pay if int(r['out']) > 0]; pay_mint = [r for r in pay if int(r['mint']) > 0]
pay_by = collections.Counter((r['sender'], r['txTo']) for r in pay)
ss_cls = collections.Counter(r['cls'] for r in ss['rows'])
json.dump([dict(tx=r['tx'], block=r['block'], epoch=r.get('epoch'), credited=str(a), takenOut=r['out'], mintedAsClaims=r['mint'], sender=r['sender'], calledContract=r['txTo'], recipient=r.get('recipient'), poolEvents=r['poolEvents'],
                betweenSyncAndSettle=r['trace']['betweenSyncAndSettle'][:3]) for r, a in zip(pay, pay_amt)], open(R + 'ssac_payout_list.json', 'w'), indent=0)
pol = jz('reread_137_w.json.gz')['rows']
def polsum(tok):
    rs = [r for r in pol if r['token'] == tok and r['cls'].startswith('surplus')]
    return len(rs), sum(sum(r['trace']['paid']) - int(r['in']) for r in rs), len({r['sender'] for r in rs})
sl = polsum('0x99a57e6c8558bc6689f894e068733adf83c19725'); sa = polsum('0x2f712578fbd1c42c3459b67dd2b9035e994bbc93')
sc = json.load(open(R + 'sender_charge_history.json')); W = sc['1']; A = sc['5042']
RPC = {n_['chainId']: n_['rpc'] for n_ in NETS}
POCKET = 'https://bsc.api.pocket.network'; SENTIO56 = 'https://bsc.rpc.sentio.xyz'; TEND = 'https://%s.gateway.tenderly.co'
WD = 'research/network-risk/cycles/006/theme-currency-lists.work/'

findings = []
# ---- F1 ibBUSD
findings.append(dict(
 ref='new',
 title='Any account can call claimFor on Alpaca ibBUSD for the PoolManager on BNB Smart Chain, which burns the whole pooled ibBUSD balance and stakes the replacement where the PoolManager cannot reach it',
 chainIds=[56], lens='L3', assumptions=['A2', 'A4', 'A6'], effect='freeze', actor='unprivileged', severity='medium',
 difference='ibBUSD 0x7c9e73d4c71dae564d41f78d56439bb4ba87592f is the share token of the closed Alpaca Finance BUSD vault on BNB Smart Chain (proxy, implementation 0xf19c0106fad0892b6d9f5db0ae1c9a2cfd14635b). Its function with selector 0xddeae033, claimFor(address), converts the ibBUSD of any holder, and the caller does not have to be that holder. The token is not attacker made and the PoolManager holds it for 16 hookless pools.',
 mechanism='1. The PoolManager keeps no total per currency. It reads the token balance only in sync and settle and pays with transfer in take (src/PoolManager.sol:279-297, 349-365, src/types/Currency.sol:60-80). A balance that a third party removes stays recorded in pool state. 2. An eth_call of claimFor(PoolManager) from the unrelated address 0x00000000000000000000000000000000000a11ce returns success on three endpoints at block 135,293,814. The same call for an address without shares reverts with the text no shares. 3. The call trace shows what the function does for the PoolManager: ibBUSD logs Transfer(PoolManager, zero address, 56658476151267410600), which is the whole balance. It then approves 55.49 units of the token 0x90476bfef61f190b54a439e2e98f8e43fb9b4a45 (symbol ibUSDT) to 0xd20b887654db8dc476007bdca83d22fa51e93407, and that contract deposits them into 0x4579587ae043131999ce3d9c66199726972e3fb7 with the PoolManager as the account and pool number 5 (selector 0x0efe6a8b). 4. After the call the PoolManager holds no ibBUSD and no ibUSDT. The ibUSDT sits in a staking contract under the PoolManager address. The PoolManager can only call transfer and balanceOf on a currency, the hook selectors on a hook and unlockCallback on its caller, so it has no way to withdraw that position. 5. I did not read the source of the staking contract and did not test whether a third party can withdraw the position for the PoolManager.',
 impact='56.658476151267410600 ibBUSD, about 56 USD at the coins.llama.fi price, held for 16 pools that were created between blocks 48,048,145 and 133,218,725. Twelve of them pair ibBUSD with USDT. Once any account sends the call, every take of ibBUSD reverts in the transfer and the liquidity providers of those pools cannot withdraw that side. The amount is small. The class is the same as the DEAD case on Base (F-085): an ordinary account empties the PoolManager balance of a token that the victims did not get from the attacker.',
 preconditions='None beyond gas. The call has not been sent yet: the PoolManager balance was 188.70 ibBUSD at block 60,000,000, 18.87 at block 120,000,000 and is 56.66 today.',
 mitigations='Liquidity providers should withdraw ibBUSD from v4 pools now. Interfaces should stop listing ibBUSD pools. The assigned balance sweep tests one token per selector family, so vault tokens with a conversion or migration function that names the holder as an argument should be listed per token on every network.',
 coreRefs=['src/PoolManager.sol:279-297', 'src/PoolManager.sol:349-365', 'src/types/Currency.sol:60-80'],
 sources=[dict(url=POCKET, supports='eth_call from 0x00000000000000000000000000000000000a11ce to ibBUSD with data 0xddeae033 and the PoolManager address returns 0x at block 135,293,814; balanceOf(PoolManager) is 56658476151267410600. The same two results came from https://bsc.rpc.sentio.xyz and https://bsc-dataseed1.bnbchain.org.'),
          dict(url='https://bsc-mainnet.nodereal.io/v1/64a9df0874fb4a93b9d0a3849de012d3', supports='debug_traceCall of the same call with callTracer and logs: burn of the whole PoolManager balance, approval of ibUSDT and deposit for the PoolManager into 0x4579587ae043131999ce3d9c66199726972e3fb7. A second trace is saved in ' + WD + 'raw/ibbusd_claimfor_trace.json.'),
          dict(url=WD + 'raw/assign_56.json.gz:1', supports='Trial sweep row of class lowered for ibBUSD and claimFor(address): the PoolManager balance fell by twice the trial amount, which was all that was left after the trial transfer.'),
          dict(url='src/types/Currency.sol:60-80', supports='take pays with transfer and reverts when the token refuses, so a missing balance blocks every payout of that currency.')],
 evidence='primary'))
