     n(ss['hi']), n(len(ss['rows'])), len(pay), ', '.join('%d %s' % (v, k) for k, v in ss_cls.items() if not k.startswith('surplus')) or 'none', amt(sum(pay_amt), 9, 6), len(pay_take), len(pay_mint),
