def tokrows(c, k): return (S[c].get('tokens') or {}).get(k, [])
tm1 = tokrows(1, 'token-moved'); tm4663 = tokrows(4663, 'token-moved'); tm137 = [x for x in tokrows(137, 'token-moved') if x[0] != '0xe0aea583266584dafbb3f9c3211d5588c73fea8d']
